import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/Transformer.html","title":"Transformer","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":1.02,"words":307},"filePathRelative":"Transformer.md"}`),a={name:`Transformer.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="transformer" tabindex="-1"><a class="header-anchor" href="#transformer"><span>Transformer</span></a></h1><p><a href="./機械翻訳.html">機械翻訳</a>の決定版。<a href="./機械学習.html">機械学習</a>。別名: <a href="./AttentionIsAllYouNeed.html">AttentionIsAllYouNeed</a></p><ul><li><a href="https://arxiv.org/abs/1706.03762" target="_blank" rel="noopener noreferrer">arxiv:1706.03762 Attention Is All You Need</a>という<a href="./論文.html">論文</a>で提唱された。</li><li><a href="https://nlp.seas.harvard.edu/annotated-transformer/" target="_blank" rel="noopener noreferrer">The Annotated Transformer</a></li><li><a href="./原論文から解き明かす生成AI.html">原論文から解き明かす生成AI</a>の3章にも詳しい</li><li><a href="https://karino2.github.io/2018/06/01/217.html" target="_blank" rel="noopener noreferrer">Attention is All You Needのメモ - なーんだ、ただの水たまりじゃないか</a> 大した事書いてないが。</li></ul><p><a href="./ConvS2S.html">ConvS2S</a>の進化版と考えられる。Convの代わりに<a href="./セルフアテンション.html">セルフアテンション</a>を使うという発明。</p><h2 id="positionembeddings" tabindex="-1"><a class="header-anchor" href="#positionembeddings"><span>PositionEmbeddings</span></a></h2><p><a href="./PositionEmbeddings.html">PositionEmbeddings</a>へ。</p><h2 id="アテンション" tabindex="-1"><a class="header-anchor" href="#アテンション"><span>アテンション</span></a></h2><ul><li><a href="./アテンション.html">アテンション</a><ul><li><a href="./SoftMax.html">SoftMax</a></li></ul></li></ul><h2 id="transformerのブロック構成" tabindex="-1"><a class="header-anchor" href="#transformerのブロック構成"><span>Transformerのブロック構成</span></a></h2><p><a href="./セルフアテンション.html">セルフアテンション</a>と<a href="./LayerNormalization.html">LayerNormalization</a>とFFNの組み合わせになっている。</p><ul><li><a href="./Transformerブロック.html">Transformerブロック</a><ul><li><a href="./セルフアテンション.html">セルフアテンション</a></li><li><a href="./LayerNormalization.html">LayerNormalization</a></li></ul></li></ul><h2 id="マスクと3つのアテンション" tabindex="-1"><a class="header-anchor" href="#マスクと3つのアテンション"><span>マスクと3つのアテンション</span></a></h2><p>アテンションの使われ方が3つあり、decoderのセルフアテンションだけmaskが必要、みたいな話が論文と本に書いてあるので、 この３つのアテンションの使われ方を見ておく。</p><h3 id="エンコーダーのセルフアテンション" tabindex="-1"><a class="header-anchor" href="#エンコーダーのセルフアテンション"><span>エンコーダーのセルフアテンション</span></a></h3><p><img src="/RandomThoughts/assets/0003-BZ_oAEun.png" alt="imgs/Transformer/0003.png"></p><h3 id="クロスアテンション" tabindex="-1"><a class="header-anchor" href="#クロスアテンション"><span>クロスアテンション</span></a></h3><p><img src="/RandomThoughts/assets/0004-mYcqpAqP.png" alt="imgs/Transformer/0004.png"></p><p>これは通常の<a href="./アテンション.html">アテンション</a>になる。<a href="./ConvS2S.html">ConvS2S</a>などと同じもの。 dを使うが、クエリに使うdは一つだけ（図ではiとしているが、実際はt-1期のもの）なのに注意。</p><h3 id="デコーダーのセルフアテンション" tabindex="-1"><a class="header-anchor" href="#デコーダーのセルフアテンション"><span>デコーダーのセルフアテンション</span></a></h3><p>これだけ未来のdが登場しうるのでマスクが必要。</p><p><img src="/RandomThoughts/assets/0005-DhCIzjZn.png" alt="imgs/Transformer/0005.png"></p><p>i番目のクエリに対してキー側にi+1番目以降のdが登場しているのに注目。eは先があってもいいがdはまだ知らない答えに相当するからまずい。</p><h2 id="decoderのクロスアテンション部分" tabindex="-1"><a class="header-anchor" href="#decoderのクロスアテンション部分"><span>Decoderのクロスアテンション部分</span></a></h2><p>Decoderは真ん中にクロスアテンションのMultiHead attentionが入る。</p><p><a href="https://nlp.seas.harvard.edu/annotated-transformer/" target="_blank" rel="noopener noreferrer">The Annotated Transformer</a>のDecoderLayerを見ると、</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code class="language-python"><span class="line"> x <span class="token operator">=</span> self<span class="token punctuation">.</span>sublayer<span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">(</span>x<span class="token punctuation">,</span> <span class="token keyword">lambda</span> x<span class="token punctuation">:</span> self<span class="token punctuation">.</span>src_attn<span class="token punctuation">(</span>x<span class="token punctuation">,</span> m<span class="token punctuation">,</span> m<span class="token punctuation">,</span> src_mask<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>となっていて、src_attnはMultiHeadedAttentionになっていて、<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>W</mi><mi>Q</mi></msub><mo separator="true">,</mo><msub><mi>W</mi><mi>K</mi></msub><mo separator="true">,</mo><msub><mi>W</mi><mi>V</mi></msub></mrow><annotation encoding="application/x-tex">W_Q, W_K, W_V</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">W</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">Q</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">W</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0715em;">K</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">W</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.2222em;">V</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>がx, m, mにそれぞれ掛けられる模様。 mはエンコーダーの最終出力(memory)。</p><h3 id="クロスアテンションをmultiheadにする意義があるのか-答-むしろクロスヘッドこそすべきらしい" tabindex="-1"><a class="header-anchor" href="#クロスアテンションをmultiheadにする意義があるのか-答-むしろクロスヘッドこそすべきらしい"><span>クロスアテンションをMultiHeadにする意義があるのか？（答. むしろクロスヘッドこそすべきらしい）</span></a></h3><p>クロスアテンションは従来の<a href="./アテンション.html">アテンション</a>とほぼ同じなのでマルチヘッドにする必要は無いのでは？とChatGPTに聞いたら以下の論文を紹介してくれた。</p><p><a href="https://arxiv.org/abs/1905.10650" target="_blank" rel="noopener noreferrer">arxiv: 1905.10650 Are Sixteen Heads Really Better than One?</a></p><p>自分の直感とは逆に、むしろクロスアテンションの方がマルチヘッド化は効くらしい。</p><p>じゃあRNNもそうなのでは？とChatGPTに聞いたらRNNは文脈ベクトルを持つ分この効果は弱くなるのではないか、との事。 真偽は試してみないとなんともいえないが、ありそうな話ではある。</p><h2 id="パラメータ数" tabindex="-1"><a class="header-anchor" href="#パラメータ数"><span>パラメータ数</span></a></h2><p><a href="./Transformerブロック.html">Transformerブロック</a>に1ブロックあたりのパラメータ数の計算はある。 <a href="./GPT1論文.html">GPT1論文</a>などと比較したくなる事もあるので全体の合計もメモしておく。</p><ul><li>base: 65M個</li><li>big: 213M個</li></ul><p>こんなものかな？</p><p>baseの丼があってるかは確認しておこう。 baseはNが6なので6個のencoderとdecoderがある。decoderはクロスアテンションで1M個追加、くらいかな。</p><p>封筒の裏計算的には</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mn>3</mn><mi>M</mi><mo>∗</mo><mn>6</mn><mo>+</mo><mn>4</mn><mi>M</mi><mo>∗</mo><mn>6</mn><mo>≃</mo><mn>42</mn><mi>M</mi></mrow><annotation encoding="application/x-tex">3M*6 + 4M*6 \\simeq 42M </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">3</span><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">∗</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">6</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">4</span><span class="mord mathnormal" style="margin-right:0.109em;">M</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">∗</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">6</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≃</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">42</span><span class="mord mathnormal" style="margin-right:0.109em;">M</span></span></span></span></span></p><p>embedは37000個のトークンを512だから18M個くらいか。これで60M個くらい。丼はあいそうか。</p>`,40)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};